import test from 'node:test';
import assert from 'node:assert';
import { createState, step, collides } from '../game/neon.js';

test('D1 - Ball plows through brick (No bounce)', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // First brick at (offsetX, 48)

  // Position ball just above the brick, moving down
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 100; // Moving DOWN
  state.ball.vx = 0;

  // Simulate one frame (dt = 0.016s)
  // We need to call the logic that is currently inside frame()
  // But the logic is inside frame(), which is a rendering function.
  // This is exactly the "debt #2" mentioned in the code.

  // To test this, we must simulate what frame() does:
  // In a real game loop: 
  // 1. step(state, dt) moves the ball.
  // 2. frame(ctx, state) checks collision.

  const dt = 0.016;
  step(state, dt); // Ball moves to y = 48 - 10 + 100*0.016 = 38 + 1.6 = 39.6. Wait, y grows down.
  // Let's recalculate.
  // Start: y = 38 (above brick at 48). vy = 100 (DOWN).
  // After step: y = 38 + 1.6 = 39.6. Still above.
  // Let's put it closer.
  state.ball.y = brick.y - 2; // 46
  step(state, dt); // y = 46 + 1.6 = 47.6. 
  // Ball radius is 7. ball.y + ball.r = 47.6 + 7 = 54.6.
  // Brick.y = 48. 54.6 > 48. Collision!

  const collision = collides(state.ball, brick);
  assert.strictEqual(collision, true, 'Ball should collide with brick');

  // Currently, frame() does NOT change vy.
  // So after "collision", vy is still 100.
  assert.strictEqual(state.ball.vy, 100, 'Ball should still have positive vy because no bounce is implemented');
});

test('D2 - Naive correction (Flip vy only) fails on side hit', () => {
  const state = createState(1);
  const brick = state.bricks[0];

  // Ball hitting the side of the brick
  state.ball.x = brick.x - 10; 
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100; // Moving RIGHT
  state.ball.vy = 0;

  const dt = 0.016;
  step(state, dt); // x = brick.x - 10 + 1.6 = brick.x - 8.4.
  // Ball radius 7. x + r = -8.4 + 7 = -1.4. Wait, x is relative to brick.x.
  // If x = brick.x - 8.4, x + r = brick.x - 1.4. Not yet colliding.

  state.ball.x = brick.x - 5;
  step(state, dt); // x = brick.x - 5 + 1.6 = brick.x - 3.4.
  // x + r = brick.x - 3.4 + 7 = brick.x + 3.6. Collision!

  const collision = collides(state.ball, brick);
  assert.strictEqual(collision, true);

  // Naive correction would flip vy. But it should flip vx.
  // Since we are testing the current code, vy is 0. 
  // If a naive fix just did `ball.vy = -ball.vy`, vy would stay 0 or become -0.
  // We want to ensure that a correct fix flips vx.
  // This test is for the "naive correction" we'll implement in our head.
});

