// --- Physics (movement + wall/paddle bounces) ------------------------------

// Handles collisions between the ball and all live bricks.
// Returns true if any brick was destroyed.
export function resolveBricks(state) {
  const { ball, bricks } = state;
  let changed = false;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    // 1. Find the closest point on the brick to the ball center
    const closestX = Math.max(brick.x, Math.min(ball.x, brick.x + brick.w));
    const closestY = Math.max(brick.y, Math.min(ball.y, brick.y + brick.h));

    // 2. Calculate distance from ball center to this closest point
    const dx = ball.x - closestX;
    const dy = ball.y - closestY;
    const distanceSq = dx * dx + dy * dy;

    if (distanceSq < ball.r * ball.r) {
      // Collision detected!
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      changed = true;

      // 3. Collision Normal
      const distance = Math.sqrt(distanceSq);

      // Avoid division by zero if ball center is exactly on the closest point
      const nx = distance === 0 ? 0 : dx / distance;
      const ny = distance === 0 ? -1 : dy / distance; // default to UP if centered

      // 4. Reflect velocity: v = v - 2 * (v . n) * n
      const dot = ball.vx * nx + ball.vy * ny;
      ball.vx -= 2 * dot * nx;
      ball.vy -= 2 * dot * ny;

      // 5. Resolve penetration (push ball out)
      const overlap = ball.r - distance;
      ball.x += nx * overlap;
      ball.y += ny * overlap;
    }
  }
  return changed;
}

// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Now also handles bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  // Sub-stepping to prevent tunneling at high speeds
  const SUB_STEPS = 5;
  const subDt = dt / SUB_STEPS;

  for (let i = 0; i < SUB_STEPS; i++) {
    const { ball, paddle } = state;

    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    resolveBricks(state);
  }

  // Exit through the bottom: ball lost
  if (state.ball.y - state.ball.r > HEIGHT) {
    return true;
  }
  return false;
}

