import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Brick Collision Tests (TDD from to_fix.md) ---

test('physics: D1 - ball bounces off brick top face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 2; 
  state.ball.vy = 100; 
  state.ball.vx = 0;

  step(state, 0.016); 
  assert.strictEqual(state.ball.vy, -100, 'Ball should have bounced UP');
});

test('physics: D2 - ball is pushed out of brick (no sticking)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 2; 
  state.ball.vy = 100; 
  state.ball.vx = 0;

  step(state, 0.016); 
  assert.strictEqual(collides(state.ball, brick), false, 'Ball should not overlap brick after resolution');
});

test('physics: D3 - ball bounces off brick side face', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 5;
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100;
  state.ball.vy = 0;

  step(state, 0.016); 
  assert.strictEqual(state.ball.vx, -100, 'Ball should have bounced LEFT');
  assert.strictEqual(state.ball.vy, 0, 'Ball vy should remain 0');
});

test('physics: D4 - ball does not tunnel at high speed', () => {
  const state = createState(6); // speed 710
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 2;
  state.ball.vy = 710;
  state.ball.vx = 0;

  step(state, 0.05); // Max dt. Tunneling distance is 35.5px.

  // The ball should have bounced and NOT ended up on the other side.
  assert.ok(state.ball.vy < 0, 'Ball should have bounced UP instead of tunneling');
  assert.strictEqual(collides(state.ball, brick), false, 'Ball should have been resolved out of the brick');
});

